def render(context):
    exec(compile('st.header(\n    "Machine Learning Model Evaluation"\n)\nst.write(\n    "Prediction target: gross OMC charger installations "\n    "in the following complete financial year."\n)\nst.info(\n    "Chronological holdout: training uses feature years "\n    "FY 2020-21 through FY 2022-23. Testing uses FY 2023-24 "\n    "features to predict FY 2024-25 installations. "\n    "Partial FY 2025-26 observations are excluded."\n)\nst.subheader(\n    "Model Performance Comparison"\n)\nst.dataframe(\n    results_df.round(3),\n    width="stretch",\n    hide_index=True,\n)\nbest_model_name = results_df.iloc[0]["Model"]\nst.success(\n    f"Lowest MAE on this holdout period: {best_model_name}"\n)\nst.caption(\n    "Lower MAE and RMSE indicate smaller prediction errors. "\n    "R² can be negative when a model performs worse than a "\n    "mean-based baseline. Results are exploratory because "\n    "the dataset contains a limited number of state-year "\n    "observations."\n)\nst.subheader(\n    "Actual vs Predicted Installations"\n)\nselected_model = st.selectbox(\n    "Select Model",\n    list(trained_models.keys()),\n)\nselected_predictions = prediction_frames[\n    selected_model\n]\ncomparison_chart = px.scatter(\n    selected_predictions,\n    x="Actual installations",\n    y="Predicted installations",\n    hover_name="State",\n    title=f"{selected_model}: Actual vs Predicted",\n    labels={\n        "Actual installations": "Actual Installations",\n        "Predicted installations": "Predicted Installations",\n    },\n)\nst.plotly_chart(\n    comparison_chart,\n    width="stretch",\n)\nst.subheader(\n    "State-wise Prediction Results"\n)\nst.dataframe(\n    selected_predictions.round(1),\n    width="stretch",\n    hide_index=True,\n)\nst.subheader(\n    "Inspect Individual State Prediction"\n)\nselected_state = st.selectbox(\n    "Select State / UT",\n    sorted(selected_predictions["State"].unique()),\n)\nstate_prediction = selected_predictions.loc[\n    selected_predictions["State"] == selected_state\n].iloc[0]\nprediction_col_1, prediction_col_2 = st.columns(2)\nprediction_col_1.metric(\n    "Actual FY 2024-25 Installations",\n    f"{int(state_prediction[\'Actual installations\']):,}",\n)\nprediction_col_2.metric(\n    "Predicted FY 2024-25 Installations",\n    f"{state_prediction[\'Predicted installations\']:,.0f}",\n)\nprediction_error = abs(\n    state_prediction["Actual installations"]\n    - state_prediction["Predicted installations"]\n)\nst.metric(\n    "Absolute Prediction Error",\n    f"{prediction_error:,.1f}",\n)\nst.caption(\n    "This is a held-out historical test prediction, "\n    "not a forecast of a future financial year."\n)', __file__, 'exec'), context)
